## 3. Core Contracts (`Core`)

```csharp
using System.Collections.Generic;
using TrafficControlSystem.Models;

namespace TrafficControlSystem.Core
{
    /// <summary>Provides the latest queue snapshot to consumers.</summary>
    public interface IQueueSnapshotProvider
    {
        QueueSnapshot GetSnapshot();
    }

    /// <summary>Accepts a queue snapshot and returns a timing plan.</summary>
    public interface ITimingPlanProvider
    {
        TimingPlan ComputePlan(QueueSnapshot snapshot);
    }

    /// <summary>Executes the plan on the physical (or simulated) hardware.</summary>
    public interface IHardwareSignalController
    {
        /// <summary>Runs the supplied plan – blocks until the whole cycle finishes.</summary>
        void ExecutePlan(TimingPlan plan);
    }
}
```

