## 4. Module #1 – Sensor Ingester

```csharp
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System;
using TrafficControlSystem.Models;
using TrafficControlSystem.Core;

namespace TrafficControlSystem.Modules.SensorIngester
{
    /// <summary>
    /// Thread‑safe ingester that receives <see cref="SensorEvent"/> objects
    /// and keeps an up‑to‑date vehicle count per lane.
    /// </summary>
    public sealed class IntersectionVehicleSensorIngester : IQueueSnapshotProvider
    {
        // lane → count of vehicles that have entered but not yet left.
        private readonly ConcurrentDictionary<LaneId, int> _laneQueues = new();

        // Optional: keep a rolling window of timestamps for advanced analytics.
        private readonly ConcurrentQueue<SensorEvent> _eventHistory = new();

        public void OnSensorEvent(SensorEvent ev)
        {
            // Increment the count for the lane.
            _laneQueues.AddOrUpdate(ev.Lane, 1, (_, old) => old + 1);
            _eventHistory.Enqueue(ev);
            // Keep history bounded (e.g., last 10 000 events) to avoid unbounded memory growth.
            while (_eventHistory.Count > 10_000 && _eventHistory.TryDequeue(out _)) { }
        }

        /// <summary>
        /// Simulates a vehicle leaving the intersection (e.g., after it passed the stop line).
        /// In a real system this would be derived from a second detector or a timer.
        /// </summary>
        public void VehicleDeparted(LaneId lane)
        {
            _laneQueues.AddOrUpdate(lane, 0, (_, old) => Math.Max(0, old - 1));
        }

        /// <inheritdoc/>
        public QueueSnapshot GetSnapshot()
        {
            // Clone the dictionary to guarantee immutability for the consumer.
            var copy = _laneQueues.ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
            return new QueueSnapshot(DateTime.UtcNow, copy);
        }
    }
}
```

*Key points*

* **ConcurrentDictionary** guarantees lock‑free updates from many sensor threads.
* The public `OnSensorEvent` method is the *only* entry point – perfect for unit‑testing with a mock sensor feed.
* The class implements **`IQueueSnapshotProvider`**, allowing the timing engine to pull data without any direct coupling.

