## 5. Module #2 – Adaptive Timing Engine

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using TrafficControlSystem.Models;
using TrafficControlSystem.Core;

namespace TrafficControlSystem.Modules.TimingEngine
{
    /// <summary>
    /// Very simple heuristic:
    ///   1. Sum queue lengths for each direction (NorthSouth vs EastWest).
    ///   2. Allocate the total cycle time proportionally.
    ///   3. Enforce configurable min / max green times.
    /// </summary>
    public sealed class AdaptiveTimingOptimizationEngine : ITimingPlanProvider
    {
        private readonly TimeSpan _totalCycle;
        private readonly TimeSpan _minGreen;
        private readonly TimeSpan _maxGreen;

        public AdaptiveTimingOptimizationEngine(
            TimeSpan totalCycle,
            TimeSpan minGreen,
            TimeSpan maxGreen)
        {
            if (minGreen > maxGreen) throw new ArgumentException("minGreen cannot be larger than maxGreen");
            if (maxGreen > totalCycle) throw new ArgumentException("maxGreen cannot exceed total cycle");
            _totalCycle = totalCycle;
            _minGreen   = minGreen;
            _maxGreen   = maxGreen;
        }

        public TimingPlan ComputePlan(QueueSnapshot snapshot)
        {
            // 1️⃣ Group lanes by direction.
            var directionQueues = new Dictionary<Direction, int>
            {
                [Direction.NorthSouth] = 0,
                [Direction.EastWest]   = 0
            };

            foreach (var kvp in snapshot.LaneQueueLengths)
            {
                Direction dir = GetDirectionFromLane(kvp.Key);
                directionQueues[dir] += kvp.Value;
            }

            // 2️⃣ Compute raw proportional green times.
            int totalVehicles = directionQueues.Values.Sum();
            // Avoid divide‑by‑zero – if no cars, split evenly.
            var rawGreen = totalVehicles == 0
                ? new Dictionary<Direction, double>
                {
                    [Direction.NorthSouth] = 0.5,
                    [Direction.EastWest]   = 0.5
                }
                : directionQueues.ToDictionary(
                    kvp => kvp.Key,
                    kvp => (double)kvp.Value / totalVehicles);

            // 3️⃣ Convert to TimeSpans and clamp.
            var greenDurations = rawGreen.ToDictionary(
                kvp => kvp.Key,
                kvp =>
                {
                    var desired = TimeSpan.FromTicks((long)(_totalCycle.Ticks * kvp.Value));
                    if (desired < _minGreen) return _minGreen;
                    if (desired > _maxGreen) return _maxGreen;
                    return desired;
                });

            // 4️⃣ Adjust to make sure the sum still equals _totalCycle.
            // Simple redistribution: if we clipped any side, give the remainder to the other.
            var sum = greenDurations.Values.Aggregate(TimeSpan.Zero, (a, b) => a + b);
            var diff = _totalCycle - sum;
            if (diff != TimeSpan.Zero)
            {
                // Give the remainder to the direction with the larger queue.
                var winner = directionQueues[Direction.NorthSouth] >= directionQueues[Direction.EastWest]
                    ? Direction.NorthSouth
                    : Direction.EastWest;
                greenDurations[winner] = greenDurations[winner] + diff;
            }

            return new TimingPlan(DateTime.UtcNow, greenDurations);
        }

        private static Direction GetDirectionFromLane(LaneId lane)
        {
            // Very simple naming convention: lanes that start with "N" or "S" belong to NS,
            // everything else (E,W) belongs to EW. Real implementations would use a config file.
            var id = lane.Id.ToUpperInvariant();
            return (id.StartsWith("N") || id.StartsWith("S")) ? Direction.NorthSouth : Direction.EastWest;
        }
    }
}
```

*Key points*

* **Heuristic** is deliberately simple so you can replace it with a more sophisticated algorithm (e.g., reinforcement‑learning) without touching the rest of the system.
* All **configuration** (cycle length, min/max greens) is injected via the constructor – ideal for unit‑tests or runtime tuning.
* The engine implements **`ITimingPlanProvider`**, exposing only the `ComputePlan` method.

